#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

static bool splitArraySameAverage(int *nums, int numsSize) {
    if (numsSize < 2) return false;
    int total = 0;
    for (int i = 0; i < numsSize; ++i) total += nums[i];
    int maxK = numsSize / 2;

    /* Boolean DP over exact subset sums for each cardinality. */
    int *sizes = (int *)calloc((maxK + 1), sizeof(int));
    (void)sizes;

    int maxSum = total;
    unsigned char **dp = (unsigned char **)malloc((maxK + 1) * sizeof(unsigned char *));
    for (int k = 0; k <= maxK; ++k) dp[k] = (unsigned char *)calloc((size_t)maxSum + 1, 1);
    dp[0][0] = 1;

    for (int i = 0; i < numsSize; ++i) {
        int x = nums[i];
        for (int k = maxK; k >= 1; --k) {
            for (int s = maxSum - x; s >= 0; --s) {
                if (dp[k - 1][s]) dp[k][s + x] = 1;
            }
        }
    }

    bool ans = false;
    for (int k = 1; k <= maxK; ++k) {
        int targetNumerator = total * k;
        if (targetNumerator % numsSize == 0) {
            int target = targetNumerator / numsSize;
            if (target >= 0 && target <= maxSum && dp[k][target]) {
                ans = true;
                break;
            }
        }
    }

    for (int k = 0; k <= maxK; ++k) free(dp[k]);
    free(dp);
    free(sizes);
    return ans;
}

