class Solution {
public:
    bool splitArraySameAverage(vector<int>& nums) {
        int n = (int)nums.size();
        if (n < 2) return false;
        int total = accumulate(nums.begin(), nums.end(), 0);
        vector<unordered_set<int>> sums(n / 2 + 1);
        sums[0].insert(0);
        for (int x : nums) {
            for (int k = n / 2; k >= 1; --k) {
                vector<int> prev(sums[k - 1].begin(), sums[k - 1].end());
                for (int s : prev) sums[k].insert(s + x);
            }
        }
        for (int k = 1; k <= n / 2; ++k) {
            int target = total * k;
            if (target % n == 0 && sums[k].count(target / n)) return true;
        }
        return false;
    }
};

