class Solution {
    public boolean splitArraySameAverage(int[] nums) {
        int n = nums.length;
        if (n < 2) return false;
        int total = 0;
        for (int x : nums) total += x;
        @SuppressWarnings("unchecked")
        HashSet<Integer>[] sums = new HashSet[n / 2 + 1];
        for (int i = 0; i < sums.length; i++) sums[i] = new HashSet<>();
        sums[0].add(0);
        for (int x : nums) {
            for (int k = n / 2; k >= 1; --k) {
                Integer[] prev = sums[k - 1].toArray(new Integer[0]);
                for (int s : prev) sums[k].add(s + x);
            }
        }
        for (int k = 1; k <= n / 2; ++k) {
            int target = total * k;
            if (target % n == 0 && sums[k].contains(target / n)) return true;
        }
        return false;
    }
}

