    static int[] parseArray(String s) {
        java.util.ArrayList<Integer> values = new java.util.ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            while (i < s.length() && (s.charAt(i) == '[' || s.charAt(i) == ']' || s.charAt(i) == ',' || Character.isWhitespace(s.charAt(i)))) i++;
            if (i >= s.length()) break;
            int sign = 1;
            if (s.charAt(i) == '-') { sign = -1; i++; }
            int v = 0;
            boolean found = false;
            while (i < s.length() && Character.isDigit(s.charAt(i))) {
                found = true;
                v = v * 10 + (s.charAt(i) - '0');
                i++;
            }
            if (found) values.add(sign * v);
            else i++;
        }
        int[] a = new int[values.size()];
        for (int j = 0; j < a.length; j++) a[j] = values.get(j);
        return a;
    }
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String line = sc.nextLine().trim();
        System.out.println(new Solution().splitArraySameAverage(parseArray(line)));
